import os
from typing import Any, Dict, List, Optional

import requests


class OCRLayoutExtractor:
    """
    Extract table cells and row structure from a document using Google Cloud Vision API.
    Requires a Google Cloud Vision API key exposed via OCRSPACE_API_KEY? No.

    This implementation uses the Google Cloud Vision REST API hosted endpoint:
    https://vision.googleapis.com/v1/images:annotate
    """

    VISION_API_URL = "https://vision.googleapis.com/v1/images:annotate"

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.getenv("GOOGLE_CLOUD_VISION_API_KEY")
        if not self.api_key:
            raise ValueError("Missing GOOGLE_CLOUD_VISION_API_KEY environment variable or api_key parameter.")

    @staticmethod
    def _bbox_to_tuple(bbox: Dict[str, Any]) -> Dict[str, int]:
        vertices = bbox.get("vertices", [])
        xs = [v.get("x", 0) for v in vertices]
        ys = [v.get("y", 0) for v in vertices]
        return {
            "x_min": min(xs) if xs else 0,
            "y_min": min(ys) if ys else 0,
            "x_max": max(xs) if xs else 0,
            "y_max": max(ys) if ys else 0,
        }

    @staticmethod
    def _parse_words(full_text_annotation: Dict[str, Any]) -> List[Dict[str, Any]]:
        words = []
        for page in full_text_annotation.get("pages", []):
            for block in page.get("blocks", []):
                for paragraph in block.get("paragraphs", []):
                    for word in paragraph.get("words", []):
                        symbols = word.get("symbols", [])
                        text = "".join(sym.get("text", "") for sym in symbols).strip()
                        if not text:
                            continue
                        words.append(
                            {
                                "text": text,
                                "bounding_box": OCRLayoutExtractor._bbox_to_tuple(word.get("boundingBox", {})),
                            }
                        )
        return words

    @staticmethod
    def _group_words_into_rows(words: List[Dict[str, Any]], y_tolerance: int = 10) -> List[List[Dict[str, Any]]]:
        if not words:
            return []

        sorted_words = sorted(words, key=lambda w: (w["bounding_box"]["y_min"], w["bounding_box"]["x_min"]))
        rows: List[List[Dict[str, Any]]] = []

        for word in sorted_words:
            y_center = (word["bounding_box"]["y_min"] + word["bounding_box"]["y_max"]) / 2
            placed = False
            for row in rows:
                row_y_center = sum((w["bounding_box"]["y_min"] + w["bounding_box"]["y_max"]) / 2 for w in row) / len(row)
                if abs(y_center - row_y_center) <= y_tolerance:
                    row.append(word)
                    placed = True
                    break
            if not placed:
                rows.append([word])

        for row in rows:
            row.sort(key=lambda w: w["bounding_box"]["x_min"])

        rows.sort(key=lambda r: min(w["bounding_box"]["y_min"] for w in r))
        return rows

    @staticmethod
    def _merge_row_to_cells(row: List[Dict[str, Any]], gap_threshold: int = 20) -> List[Dict[str, Any]]:
        if not row:
            return []

        cells = []
        current = [row[0]]
        for prev, curr in zip(row, row[1:]):
            prev_box = prev["bounding_box"]
            curr_box = curr["bounding_box"]
            gap = curr_box["x_min"] - prev_box["x_max"]
            if gap > gap_threshold:
                cells.append(current)
                current = [curr]
            else:
                current.append(curr)
        cells.append(current)

        normalized = []
        for cell_words in cells:
            text = " ".join(w["text"] for w in cell_words).strip()
            x_min = min(w["bounding_box"]["x_min"] for w in cell_words)
            y_min = min(w["bounding_box"]["y_min"] for w in cell_words)
            x_max = max(w["bounding_box"]["x_max"] for w in cell_words)
            y_max = max(w["bounding_box"]["y_max"] for w in cell_words)
            normalized.append(
                {
                    "text": text,
                    "bounding_box": {"x_min": x_min, "y_min": y_min, "x_max": x_max, "y_max": y_max},
                }
            )
        return normalized

    def extract_table_structure(self, image_path: str) -> Dict[str, Any]:
        with open(image_path, "rb") as f:
            image_bytes = f.read()

        # Google Cloud Vision expects base64-encoded image content in the request body.
        import base64

        payload = {
            "requests": [
                {
                    "image": {"content": base64.b64encode(image_bytes).decode("utf-8")},
                    "features": [{"type": "DOCUMENT_TEXT_DETECTION"}],
                }
            ]
        }

        response = requests.post(
            f"{self.VISION_API_URL}?key={self.api_key}",
            json=payload,
            timeout=120,
        )
        response.raise_for_status()
        result = response.json()

        annotations = result.get("responses", [{}])[0]
        full_text_annotation = annotations.get("fullTextAnnotation", {})

        words = self._parse_words(full_text_annotation)
        rows = self._group_words_into_rows(words)

        table_rows = []
        for row_idx, row in enumerate(rows):
            cells = self._merge_row_to_cells(row)
            table_rows.append(
                {
                    "row_index": row_idx,
                    "cells": [
                        {
                            "cell_index": cell_idx,
                            "text": cell["text"],
                            "bounding_box": cell["bounding_box"],
                        }
                        for cell_idx, cell in enumerate(cells)
                    ],
                }
            )

        return {
            "provider": "google_cloud_vision",
            "table_rows": table_rows,
            "word_count": len(words),
        }


def extract_table_cells_and_rows(document_path: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    extractor = OCRLayoutExtractor(api_key=api_key)
    return extractor.extract_table_structure(document_path)
